import{z as n,x as s,o as l,c as d,q as r,j as o,D as e,d as A,s as t,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"LoRA 生命周期管理","description":"","frontmatter":{"title":"LoRA 生命周期管理","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-lora-lifecycle.md","filePath":"llm/continual-lora-lifecycle.md","lastUpdated":1791413859000}'),m={name:"llm/continual-lora-lifecycle.md"};function p(D,E,f,u,h,c){const B=s("Mermaid");return l(),d("div",null,[E[2]||(E[2]=r('<h1 id="lora-生命周期管理" tabindex="-1">LoRA 生命周期管理 <a class="header-anchor" href="#lora-生命周期管理" aria-label="Permalink to &quot;LoRA 生命周期管理&quot;">​</a></h1><div class="epigraph"><p>冻结基座等于宣布：旧能力不需要保护，因为它从未被触碰；持续学习从改写权重变成管理模块的版本。</p><footer>—— 据 Hu 等 2021（LoRA）与 Biderman 等 2024 整理</footer></div><p><a href="/llm/continual-replay-buffer">上一课</a>把旧梯度混回批次，保护发生在数据侧； LoRA 把保护移进结构侧：基座全程冻结，只训低秩增量 \\(\\Delta W=BA\\)。主干<a href="/llm/lora">LoRA</a>一课讲过它的参数效率，<a href="/llm/multi-lora-serving">多 LoRA 服务</a>讲过部署形态；本课把它当持续学习的载体，写一个适配器从候选到退役的完整生命周期，以及生命周期里每个门该拦什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>生产环要的是「经常更新、不翻车」。全参微调每次更新都重写所有权重，<a href="/llm/continual-forgetting-mechanism">第一课</a>的三条通路全开；LoRA 把扰动限制在每层 \\(r\\) 维子空间里，基座函数被结构性地保持——适配器一摘，模型精确回到原样。新的问题随之而来：适配器越攒越多，何时合进基座、何时下线；滚动更新同一个适配器时，遗忘没有消失，只是搬进了增量子空间内部。</p><p><span class="marginnote">「绑死基座版本」指适配器必须记下自己是在哪个基座快照上训的：增量 \\(\\Delta W=BA\\) 只有加回那个原权重，形状与含义才成立。基座一升级，增量等于失去了「被减数」，必须重验甚至重训——这是适配器版本管理里最容易翻车的细节。</span></p><h3 id="生命周期的状态机" tabindex="-1">生命周期的状态机 <a class="header-anchor" href="#生命周期的状态机" aria-label="Permalink to &quot;生命周期的状态机&quot;">​</a></h3><p>候选态：训练完成、绑死基座版本与训练配方，未评测不进流量。灰度态：经<a href="/llm/adapter-hot-swap">适配器热更新</a>挂小流量，按任务成绩与延迟门限观察。在役态：全量路由，路由错误率是健康指标。退役态：合并、归档或删除，归档必须带数据配方，否则只剩一个不能再生的二进制。每次迁移都要有判据，判据来自<a href="/llm/forgetting-metrics">遗忘的度量</a>同款协议：新任务达标，旧能力探针不出带宽。</p><p><span class="marginnote">Biderman 等 2024 的结论是双向的：相同步数与数据下，LoRA 比全参微调学得少，也忘得少。选型因此不是「LoRA 是否更优」，而是当前任务需要多少可塑性——重行为的任务适配器够用，重要识或风格重写往往推不动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>更新策略先于训练细节。按域分片：每个业务域一个适配器，互相隔离，遗忘被限制在域内；代价是路由复杂，跨域请求要决定挂几个。滚动更新：整个流共用一个适配器，周期性重训，操作最简单，遗忘风险全在增量内部，必须配上<a href="/llm/continual-replay-buffer">上一课</a>的回放——基座冻结挡大破坏，回放挡增量内部的小漂移。</p><p>合入是生命周期里最重的一道门：把在役适配器并进基座，省掉路由开销，但这版基座从此承载该域的行为，回滚粒度变粗。<a href="/llm/lora-merge-conflict">LoRA 合并与冲突</a>的判据——秩冲突与方向干涉——就是这道门的验收项。动基座之前先问：这个域未来一个月还会频繁更新吗。</p>',12)),(l(),o(i,null,{default:e(()=>[t(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRAIN%5B%22%E6%8C%89%E5%9F%9F%E8%AE%AD%E7%BB%83%20%CE%94W%3DBA%22%5D%20--%3E%20EVAL%5B%22%E8%AF%84%E6%B5%8B%EF%BC%9A%E6%96%B0%E4%BB%BB%E5%8A%A1%E8%BE%BE%E6%A0%87%2B%E6%97%A7%E6%8E%A2%E9%92%88%E4%B8%8D%E5%87%BA%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20EVAL%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20TUNE%5B%22%E8%B0%83%E7%A7%A9%E6%88%96%E8%A1%A5%E5%9B%9E%E6%94%BE%E6%95%B0%E6%8D%AE%22%5D%0A%20%20TUNE%20--%3E%20TRAIN%0A%20%20EVAL%20--%3E%7C%E8%BF%87%7C%20CANARY%5B%22%E7%83%AD%E6%9B%B4%E6%96%B0%E6%8C%82%E7%81%B0%E5%BA%A6%22%5D%0A%20%20CANARY%20--%3E%20SERVE%5B%22%E5%9C%A8%E5%BD%B9%EF%BC%9A%E5%A4%9ALoRA%E8%B7%AF%E7%94%B1%22%5D%0A%20%20SERVE%20--%3E%20DEC%7B%22%E8%AF%A5%E5%9F%9F%E8%BF%98%E8%A6%81%E9%A2%91%E7%B9%81%E6%9B%B4%E6%96%B0%E5%90%97%3F%22%7D%0A%20%20DEC%20--%3E%7C%E6%98%AF%7C%20TRAIN%0A%20%20DEC%20--%3E%7C%E5%90%A6%7C%20MERGE%5B%22%E5%B9%B6%E5%85%A5%E5%9F%BA%E5%BA%A7%E6%88%96%E5%BD%92%E6%A1%A3%E9%80%80%E5%BD%B9%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"用数字感受 \\(r\\) 的省参程度：一个 \\(4096\\times4096\\) 的权重矩阵约有 1677 万个参数；取 \\(r=8\\) 时，LoRA 只训 \\(4096\\times8+8\\times4096\\approx6.5\\) 万个，不到原矩阵的 0.4%。代价是更新被限制在 8 维子空间里，能装下的行为变化相应变少。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[A("低秩约束为什么抗遗忘：\\(\\Delta W\\) 的秩不超过 \\(r\\)，参数移动被压进子空间，基座函数在其余方向精确不动；遗忘只能通过子空间与旧功能方向的交叠发生。\\(r\\) 因此是可塑性旋钮：太小学不动，太大逼近全参、把遗忘请回来，"),a("a",{href:"/llm/adalora"},"AdaLoRA"),A("式的按重要性分配秩是这条轴上的自动化尝试。")],-1)),E[6]||(E[6]=a("p",null,"隔离为什么便宜：多个适配器并存时，各域行为物理上不共享权重，串扰只可能发生在路由层——没挂上的域连被破坏的通道都没有。代价是复杂度挪到服务侧：适配器与基座的版本配对必须显式管理，基座一升级，所有适配器重验兼容，这是最易省略也最常出事故的一步。",-1)),(l(),o(i,null,{default:e(()=>[t(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E6%BB%9A%E5%8A%A8%E6%9B%B4%E6%96%B0%E5%90%8C%E4%B8%80%E9%80%82%E9%85%8D%E5%99%A8%22%5D%20--%3E%20SUB%5B%22%E6%96%B0%E6%95%B0%E6%8D%AE%E6%8E%A8%20%CE%94W%20%E5%9C%A8%20r%20%E7%BB%B4%E5%AD%90%E7%A9%BA%E9%97%B4%E5%86%85%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20SUB%20--%3E%20OV%7B%22%E4%B8%8E%E6%97%A7%E5%8A%9F%E8%83%BD%E6%96%B9%E5%90%91%E4%BA%A4%E5%8F%A0%3F%22%7D%0A%20%20OV%20--%3E%7C%E4%B8%8D%E4%BA%A4%E5%8F%A0%7C%20SAFE%5B%22%E5%9F%BA%E5%BA%A7%E6%96%B9%E5%90%91%E7%B2%BE%E7%A1%AE%E4%B8%8D%E5%8A%A8%3A%E6%97%A0%E9%81%97%E5%BF%98%22%5D%0A%20%20OV%20--%3E%7C%E4%BA%A4%E5%8F%A0%7C%20FORGET%5B%22%E5%AD%90%E7%A9%BA%E9%97%B4%E5%86%85%E9%81%97%E5%BF%98%3A%E6%97%A7%E8%A1%8C%E4%B8%BA%E6%8E%89%E5%88%86%22%5D%0A%20%20FORGET%20--%3E%20REPLAY%5B%22%E5%9B%9E%E6%94%BE%20%2B%20%E6%8E%A2%E9%92%88%E5%B8%A6%E5%AE%BD%E5%85%9C%E5%BA%95%22%5D%0A%20%20BASE%5B%22%E5%9F%BA%E5%BA%A7%E5%86%BB%E7%BB%93%22%5D%20-.-%3E%7C%22%E7%BB%93%E6%9E%84%E6%80%A7%E6%8C%A1%E4%BD%8F%E5%A4%A7%E7%A0%B4%E5%9D%8F%22%7C%20SAFE%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=r('<p><span class="marginnote">初学者容易把「基座冻结」当成「不会遗忘」的保证。它挡住的只是适配器之外的权重变化；同一个适配器滚动更新时，新旧 \\(\\Delta W\\) 在同一个子空间里互相覆盖，遗忘照常发生——只是范围变小，不是消失，探针与回放一样不能省。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>适配器方案的两个上限要说清。一是可塑性上限：重要识、大规模风格或知识注入，低秩增量常常装不下，Biderman 等的「学得少」就是这半句；硬塞的结果是探针通过但任务质量平庸。二是基座上限：适配器不会让基座变聪明，世界知识过期时，该动的是基座与预训练配比，不是再加一层增量。另外，隔离不是免费的遗忘豁免——滚动更新同一适配器时，子空间内部的漂移照旧发生，回放与探针一个都不能省。</p><p>最后，别把生命周期管理做成纸面流程：每个状态迁移的判据要能自动执行，灰度要能自动回滚。流程写在文档里而判据不在流水线里，等于没有流程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>冻结基座把遗忘问题转化为模块管理问题：旧能力结构性保持，摘下适配器即精确还原。</li><li>生命周期是状态机：候选、灰度、在役、退役，每次迁移挂着自动执行的判据。</li><li>更新策略二选一：按域分片换隔离，滚动更新省事但必须配回放。</li><li>\\(r\\) 是可塑性旋钮；LoRA 学得少也忘得少，按任务需要的可塑性选型。</li><li>合并是单向门：并入基座前用秩冲突与方向干涉验收，并考虑该域的更新频率。</li><li>出处：Hu 等 2021（LoRA）；Biderman 等 2024（LoRA Learns Less and Forgets Less）；Rebuffi 等 2017 的多任务适配谱系。</li></ul>',6))])}const F=n(m,[["render",p]]);export{R as __pageData,F as default};
